import React, { useState } from "react";
import Header from "../components/Header";
import VoiceButton from "../components/VoiceButton";
import { sendVoiceText } from "../services/api";
import "./Chat.css";

export default function Chat() {
  const [input, setInput] = useState("");
  const [messages, setMessages] = useState([]);

  const askAI = async (text) => {
    const value = text.trim();
    if (!value) return;

    setMessages((old) => [
      ...old,
      { role: "user", text: value }
    ]);
    setInput("");

    try {
      const result = await sendVoiceText(value);

      setMessages((old) => [
        ...old,
        {
          role: "ai",
          text: result.response || "I received your message."
        }
      ]);

      if ("speechSynthesis" in window) {
        const speech = new SpeechSynthesisUtterance(
          result.response || "I received your message."
        );
        window.speechSynthesis.speak(speech);
      }
    } catch {
      const response =
        "Your voice was recognized. Connect the backend AI service to generate intelligent responses.";

      setMessages((old) => [
        ...old,
        { role: "ai", text: response }
      ]);
    }
  };

  const submit = (e) => {
    e.preventDefault();
    askAI(input);
  };

  return (
    <div className="chat-page">
      <Header />

      <main className="chat-main">
        <div className="chat-shell">
          <div className="chat-header">
            <div>
              <p className="eyebrow">VOICE ASSISTANT</p>
              <h1>AI Conversation</h1>
            </div>
            <span className="online-status">
              <span /> Online
            </span>
          </div>

          <div className="messages">
            {messages.length === 0 ? (
              <div className="empty-chat">
                <h2>Start talking to AI</h2>
                <p>
                  Click the microphone and speak. Your speech will be
                  converted to text and the AI will respond.
                </p>
                <VoiceButton onResult={askAI} />
              </div>
            ) : (
              messages.map((message, index) => (
                <div
                  key={index}
                  className={`message ${message.role}`}
                >
                  <span className="message-label">
                    {message.role === "user" ? "You" : "AI"}
                  </span>
                  <p>{message.text}</p>
                </div>
              ))
            )}
          </div>

          <form className="chat-input" onSubmit={submit}>
            <input
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Type your message..."
            />
            <VoiceButton onResult={askAI} />
            <button type="submit">Send</button>
          </form>
        </div>
      </main>
    </div>
  );
}
